// StaticModelHarnessSaveAt is engine's whole state at the macrostep boundary it
// stands at: every variable, the machine's own included, and where it stands, as
// the `sce-saved-state` document every backend reads (sce.SavedState.ToJSON).
// Each delayed `<send>` still waiting is written as the moment it comes due on
// the wall clock whose reading now is wallNowMs, in milliseconds since the Unix
// epoch.
//
// Refused for a machine that is not running, one that has ended, one whose last
// macrostep stopped at the microstep ceiling, and one built around another
// document's policy.
func StaticModelHarnessSaveAt(engine *sce.Engine[StaticModelHarnessState, StaticModelHarnessEvent], wallNowMs int64) (*sce.SavedState, error) {
	p, ok := engine.Policy().(*StaticModelHarnessPolicy)
	if !ok {
		return nil, sce.Refuse("the engine is not one of StaticModelHarness")
	}
	variables := sce.NewJSONObject()
	variables.Set("offered", sce.SavedWriteList(p.vOffered, sce.SavedWriteUint32))
	variables.Set("request", sce.SavedWriteString(p.vRequest))
	variables.Set("prompt", sce.SavedWriteString(p.vPrompt))
	variables.Set("said", sce.SavedWriteString(p.vSaid))
	variables.Set("offered_ok", sce.SavedWriteBool(p.vOfferedOk))
	variables.Set("refused", p.vRefused.ToSaved())
	variables.Set("refusals", sce.SavedWriteList(p.vRefusals, func(r StaticModelHarnessRefusalRecord) any { return r.ToSaved() }))
	variables.Set("attempts", sce.SavedWriteUint32(p.vAttempts))
	variables.Set("outcome", sce.SavedWriteString(p.vOutcome))
	variables.Set("answer", optional.Wire(p.vAnswer, func(v StaticModelHarnessAnswerRecord) any { return v.ToSaved() }))
	variables.Set("why", optional.Wire(p.vWhy, func(v StaticModelHarnessLiftRefusalRecord) any { return v.ToSaved() }))
	var children []sce.SavedChild
	return sce.SaveSession(engine, &StaticModelHarnessSavedShape, variables,
		sce.SaveHistory[StaticModelHarnessState, StaticModelHarnessEvent](p, StaticModelHarnessHistories),
		children, wallNowMs)
}

// StaticModelHarnessSave is StaticModelHarnessSaveAt at the host's wall clock now.
func StaticModelHarnessSave(engine *sce.Engine[StaticModelHarnessState, StaticModelHarnessEvent]) (*sce.SavedState, error) {
	return StaticModelHarnessSaveAt(engine, sce.SavedWallClockMs())
}

// StaticModelHarnessJudge refuses saved unless a machine of this document could
// restore it, building nothing: what a parent's restore asks of each child it
// holds (docs/adr/0045, section 3, step 1).
func StaticModelHarnessJudge(saved *sce.SavedState) error {
	p := &StaticModelHarnessPolicy{}
	grown, err := sce.UpgradeSavedState(saved, &StaticModelHarnessSavedShape)
	if err != nil {
		return err
	}
	if _, err := sce.RestoreHistory[StaticModelHarnessState, StaticModelHarnessEvent](p, grown, StaticModelHarnessHistories); err != nil {
		return err
	}
	if raw, err := grown.Variable("offered"); err != nil {
		return err
	} else if _, err := sce.SavedReadList(raw, "offered", 8, sce.SavedReadUint32); err != nil {
		return err
	}
	if raw, err := grown.Variable("request"); err != nil {
		return err
	} else if _, err := sce.SavedReadBoundedString(raw, "request", 512); err != nil {
		return err
	}
	if raw, err := grown.Variable("prompt"); err != nil {
		return err
	} else if _, err := sce.SavedReadBoundedString(raw, "prompt", 8192); err != nil {
		return err
	}
	if raw, err := grown.Variable("said"); err != nil {
		return err
	} else if _, err := sce.SavedReadBoundedString(raw, "said", 4096); err != nil {
		return err
	}
	if raw, err := grown.Variable("offered_ok"); err != nil {
		return err
	} else if _, err := sce.SavedReadBool(raw, "offered_ok"); err != nil {
		return err
	}
	if raw, err := grown.Variable("refused"); err != nil {
		return err
	} else if _, err := StaticModelHarnessRefusalRecordFromSaved(raw, "refused"); err != nil {
		return err
	}
	if raw, err := grown.Variable("refusals"); err != nil {
		return err
	} else if _, err := sce.SavedReadList(raw, "refusals", 3, StaticModelHarnessRefusalRecordFromSaved); err != nil {
		return err
	}
	if raw, err := grown.Variable("attempts"); err != nil {
		return err
	} else if _, err := sce.SavedReadUint32(raw, "attempts"); err != nil {
		return err
	}
	if raw, err := grown.Variable("outcome"); err != nil {
		return err
	} else if _, err := sce.SavedReadBoundedString(raw, "outcome", 24); err != nil {
		return err
	}
	if raw, err := grown.Variable("answer"); err != nil {
		return err
	} else if _, err := sce.SavedReadOptional(raw, "answer", StaticModelHarnessAnswerRecordFromSaved, optional.None[StaticModelHarnessAnswerRecord], optional.Some[StaticModelHarnessAnswerRecord]); err != nil {
		return err
	}
	if raw, err := grown.Variable("why"); err != nil {
		return err
	} else if _, err := sce.SavedReadOptional(raw, "why", StaticModelHarnessLiftRefusalRecordFromSaved, optional.None[StaticModelHarnessLiftRefusalRecord], optional.Some[StaticModelHarnessLiftRefusalRecord]); err != nil {
		return err
	}
	return sce.JudgeSession[StaticModelHarnessState, StaticModelHarnessEvent](p, grown)
}

// StaticModelHarnessRestoreAt is a machine of policy standing where saved left
// one, measuring time by clock: in place of `Initialize`, so no `<onentry>` runs
// and no `<data>` is evaluated, since the saved run already did both. Every value
// is read and the state judged before any is written, so a refused restore leaves
// policy as it was.
//
// Each delayed `<send>` saved is armed against clock, which is the one the
// machine measures time by; wallNowMs is what time it is on the wall clock the
// saved `due`s were written against. A send comes due when its saved moment does,
// and one already due comes due now.
//
// The host registers its invokers and its processors on the machine this
// returns, and drives it as it would one it had initialized.
func StaticModelHarnessRestoreAt(policy *StaticModelHarnessPolicy, saved *sce.SavedState, clock sce.SceClock, wallNowMs int64) (*sce.Engine[StaticModelHarnessState, StaticModelHarnessEvent], error) {
	// The state as one of this machine: each record saved at an earlier revision
	// of its schema holds the defaults of the fields added since.
	grown, err := sce.UpgradeSavedState(saved, &StaticModelHarnessSavedShape)
	if err != nil {
		return nil, err
	}
	history, err := sce.RestoreHistory[StaticModelHarnessState, StaticModelHarnessEvent](policy, grown, StaticModelHarnessHistories)
	if err != nil {
		return nil, err
	}
	raw1, err := grown.Variable("offered")
	if err != nil {
		return nil, err
	}
	read1, err := sce.SavedReadList(raw1, "offered", 8, sce.SavedReadUint32)
	if err != nil {
		return nil, err
	}
	raw2, err := grown.Variable("request")
	if err != nil {
		return nil, err
	}
	read2, err := sce.SavedReadBoundedString(raw2, "request", 512)
	if err != nil {
		return nil, err
	}
	raw3, err := grown.Variable("prompt")
	if err != nil {
		return nil, err
	}
	read3, err := sce.SavedReadBoundedString(raw3, "prompt", 8192)
	if err != nil {
		return nil, err
	}
	raw4, err := grown.Variable("said")
	if err != nil {
		return nil, err
	}
	read4, err := sce.SavedReadBoundedString(raw4, "said", 4096)
	if err != nil {
		return nil, err
	}
	raw5, err := grown.Variable("offered_ok")
	if err != nil {
		return nil, err
	}
	read5, err := sce.SavedReadBool(raw5, "offered_ok")
	if err != nil {
		return nil, err
	}
	raw6, err := grown.Variable("refused")
	if err != nil {
		return nil, err
	}
	read6, err := StaticModelHarnessRefusalRecordFromSaved(raw6, "refused")
	if err != nil {
		return nil, err
	}
	raw7, err := grown.Variable("refusals")
	if err != nil {
		return nil, err
	}
	read7, err := sce.SavedReadList(raw7, "refusals", 3, StaticModelHarnessRefusalRecordFromSaved)
	if err != nil {
		return nil, err
	}
	raw8, err := grown.Variable("attempts")
	if err != nil {
		return nil, err
	}
	read8, err := sce.SavedReadUint32(raw8, "attempts")
	if err != nil {
		return nil, err
	}
	raw9, err := grown.Variable("outcome")
	if err != nil {
		return nil, err
	}
	read9, err := sce.SavedReadBoundedString(raw9, "outcome", 24)
	if err != nil {
		return nil, err
	}
	raw10, err := grown.Variable("answer")
	if err != nil {
		return nil, err
	}
	read10, err := sce.SavedReadOptional(raw10, "answer", StaticModelHarnessAnswerRecordFromSaved, optional.None[StaticModelHarnessAnswerRecord], optional.Some[StaticModelHarnessAnswerRecord])
	if err != nil {
		return nil, err
	}
	raw11, err := grown.Variable("why")
	if err != nil {
		return nil, err
	}
	read11, err := sce.SavedReadOptional(raw11, "why", StaticModelHarnessLiftRefusalRecordFromSaved, optional.None[StaticModelHarnessLiftRefusalRecord], optional.Some[StaticModelHarnessLiftRefusalRecord])
	if err != nil {
		return nil, err
	}
	if err := sce.JudgeSession[StaticModelHarnessState, StaticModelHarnessEvent](policy, grown); err != nil {
		return nil, err
	}
	policy.vOffered = read1
	policy.vRequest = read2
	policy.vPrompt = read3
	policy.vSaid = read4
	policy.vOfferedOk = read5
	policy.vRefused = read6
	policy.vRefusals = read7
	policy.vAttempts = read8
	policy.vOutcome = read9
	policy.vAnswer = read10
	policy.vWhy = read11
	for _, recorded := range history {
		policy.SetHistoryValue(recorded.History, recorded.States)
	}
	return sce.EnterSession[StaticModelHarnessState, StaticModelHarnessEvent](policy, grown, clock, wallNowMs)
}

