// ── SCE Accepted Subset 2.12: typed host-run invoke interface ──────────
// StaticModelHarnessGenRequest is `sce:request`: the record the host is asked to start `<invoke id="gen">`
// with (SCE Accepted Subset §2.12).
type StaticModelHarnessGenRequest struct {
	Prompt string
	AnswerSchema string
	MaxTokens uint32
	TemperatureMilli uint16
}

// StaticModelHarnessGenResult is `sce:result`: the record the host completes `<invoke id="gen">`
// with (SCE Accepted Subset §2.12).
type StaticModelHarnessGenResult struct {
	Error string
	Text string
	Constrained bool
	Model string
	PromptTokens uint32
	AnswerTokens uint32
	Finish string
}

// Wire is the JSON `done.invoke.gen` carries this record as.
func (r StaticModelHarnessGenResult) Wire() string {
	return sce.PayloadJSON(sce.Pair("error", r.Error), sce.Pair("text", r.Text), sce.Pair("constrained", r.Constrained), sce.Pair("model", r.Model), sce.Pair("prompt_tokens", r.PromptTokens), sce.Pair("answer_tokens", r.AnswerTokens), sce.Pair("finish", r.Finish))
}

// StaticModelHarnessSceHostModelGenerateInvoker is the host side of this document's typed
// `<invoke type="sce-host-model-generate">`s (SCE Accepted Subset §2.12). Register it with
// RegisterStaticModelHarnessSceHostModelGenerateInvoker.
type StaticModelHarnessSceHostModelGenerateInvoker interface {
	// StartGen is §scxml-6.4: begin `<invoke id="gen">`. token names
	// this start; a host that finishes later hands it back to
	// CompleteStaticModelHarnessGen (or CompleteHostInvoke). Non-nil completes
	// the invocation now.
	StartGen(request StaticModelHarnessGenRequest, token uint64) *StaticModelHarnessGenResult
	// CancelGen is §scxml-6.4: `<invoke id="gen">`'s state exited while
	// the start token names was still running. Stop it.
	CancelGen(token uint64)
}

// RegisterStaticModelHarnessSceHostModelGenerateInvoker registers invoker as the handler for
// `type="sce-host-model-generate"`.
func RegisterStaticModelHarnessSceHostModelGenerateInvoker(e *sce.Engine[StaticModelHarnessState, StaticModelHarnessEvent], invoker StaticModelHarnessSceHostModelGenerateInvoker) {
	e.RegisterInvoker("sce-host-model-generate", func(event sce.HostInvokeEvent) *sce.HostInvokeResponse {
		if start := event.Start; start != nil {
			switch start.InvokeID {
			case "gen":
				typed := StaticModelHarnessGenRequest{Prompt: sce.RequestString(*start, "prompt"), AnswerSchema: sce.RequestString(*start, "answer_schema"), MaxTokens: sce.RequestUnsigned[uint32](*start, "max_tokens"), TemperatureMilli: sce.RequestUnsigned[uint16](*start, "temperature_milli")}
				if result := invoker.StartGen(typed, start.Token); result != nil {
					data := result.Wire()
					return &sce.HostInvokeResponse{DoneData: &data}
				}
				return nil
			}
			return nil
		}
		if cancel := event.Cancel; cancel != nil {
			switch cancel.InvokeID {
			case "gen":
				invoker.CancelGen(cancel.Token)
				return nil
			}
			return nil
		}
		return nil
	})
}

// CompleteStaticModelHarnessGen completes `<invoke id="gen">`'s start token
// with its record — CompleteHostInvoke with the record's JSON, so a stale
// or unknown token is refused the same way (false).
func CompleteStaticModelHarnessGen(e *sce.Engine[StaticModelHarnessState, StaticModelHarnessEvent], token uint64, result StaticModelHarnessGenResult) bool {
	return e.CompleteHostInvoke("sce-host-model-generate", "gen", token, result.Wire())
}


