// NewStaticModelHarnessPolicy creates a new policy with default values.
func NewStaticModelHarnessPolicy() StaticModelHarnessPolicy {
	var vOffered []uint32 = nil
	var vRequest string = ""
	var vPrompt string = ""
	var vSaid string = ""
	var vOfferedOk bool = false
	var vRefused StaticModelHarnessRefusalRecord = StaticModelHarnessRefusalRecord{code: StaticModelHarnessHarnessCodeEnumNotJson, path: ""}
	var vRefusals []StaticModelHarnessRefusalRecord = nil
	var vAttempts uint32 = 0
	var vOutcome string = ""
	var vAnswer optional.Of[StaticModelHarnessAnswerRecord] = optional.None[StaticModelHarnessAnswerRecord]()
	var vWhy optional.Of[StaticModelHarnessLiftRefusalRecord] = optional.None[StaticModelHarnessLiftRefusalRecord]()
	return StaticModelHarnessPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by and
		// a peer addresses it by. A host that has one for it gives it with
		// SetSessionID before it starts the machine; a child's is its parent's
		// and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vOffered: vOffered,
		vRequest: vRequest,
		vPrompt: vPrompt,
		vSaid: vSaid,
		vOfferedOk: vOfferedOk,
		vRefused: vRefused,
		vRefusals: vRefusals,
		vAttempts: vAttempts,
		vOutcome: vOutcome,
		vAnswer: vAnswer,
		vWhy: vWhy,
		pendingInvokes: make([]sce.PendingInvoke[StaticModelHarnessState], 0),
		activeInvokes:  make(map[string]*sce.ChildSession),
	}
}

// SetSessionID gives this session the id its host has for it, in place of the
// one it drew: an XML Nmtoken, since another session addresses this one as
// `#_scxml_<id>` and every child's id is this one's and the id the child was
// started under (docs/adr/0045). Refused for anything else. Called before the
// machine starts, since what it sends names it by the id it began with.
// Declared whether or not a saved state can hold the machine: a root's id is
// bound when the machine is created, whether or not it saves.
func (p *StaticModelHarnessPolicy) SetSessionID(id string) error {
	if reason := sce.SessionIDRefusalOf(id); reason != "" {
		return sce.Refuse(reason)
	}
	p.SessionID = id
	return nil
}

// Offered reports what the published `offered` datamodel
