// ExecutePendingInvokes starts deferred child state machines (W3C SCXML 6.4).
// Port of Rust do_execute_pending_invokes().
func (p *StaticModelHarnessPolicy) ExecutePendingInvokes(engine *sce.Engine[StaticModelHarnessState, StaticModelHarnessEvent]) {
	if len(p.pendingInvokes) == 0 {
		return
	}

	// W3C SCXML 6.4: Copy-and-clear to prevent iterator invalidation
	invokesToExecute := make([]sce.PendingInvoke[StaticModelHarnessState], len(p.pendingInvokes))
	copy(invokesToExecute, p.pendingInvokes)
	p.pendingInvokes = p.pendingInvokes[:0]

	for _, pending := range invokesToExecute {
		if pending.DocumentID == "gen" {
			// W3C SCXML 6.4.1: the host declared this `type`, so START the
			// invocation rather than refusing it. The id handed over is the
			// DOCUMENT's, not the per-instance one the pending queue carries:
			// `done.invoke.<id>` is the name the author wrote a transition
			// for, so it is the name the host must answer on.
			// W3C SCXML 6.4.1: what the request says is evaluated now, when the
			// invocation starts, by the rules the other invoke kinds follow: an
			// attribute that cannot be evaluated starts nothing, and a `<param>`
			// that cannot is reported and left out (W3C SCXML 5.7.1).
			hostInvokeSrc := ""
			hostInvokeContent := ""
			hostInvokeParams := map[string][]string{}
			// The same pairs as the data model holds them, for the request's
			// EventData: one evaluation, read as text for Params and typed for
			// the JSON.
			hostInvokePayload := make([]sce.EventDataParam, 0)
			// SCE Accepted Subset 2.12: `sce:request` makes the params a record,
			// so each value is held to its field here, where the invocation
			// starts; one that does not fit starts nothing.
			requestRefused := false
			if !requestRefused {
				sceValue := p.vPrompt
				hostInvokeParams["prompt"] = append(hostInvokeParams["prompt"], sce.ToWireString(sceValue))
				hostInvokePayload = append(hostInvokePayload, sce.EventDataParam{Name: "prompt", Value: sceValue})
			}
			if !requestRefused {
				sceValue := int64(256)
				hostInvokeParams["max_tokens"] = append(hostInvokeParams["max_tokens"], sce.ToWireString(sceValue))
				hostInvokePayload = append(hostInvokePayload, sce.EventDataParam{Name: "max_tokens", Value: sceValue})
			}
			if !requestRefused {
				sceValue := int64(0)
				hostInvokeParams["temperature_milli"] = append(hostInvokeParams["temperature_milli"], sce.ToWireString(sceValue))
				hostInvokePayload = append(hostInvokePayload, sce.EventDataParam{Name: "temperature_milli", Value: sceValue})
			}
			{
				sceValue := int64(8000)
				hostInvokeParams["_sce_deadline_ms"] = append(hostInvokeParams["_sce_deadline_ms"], sce.ToWireString(sceValue))
				hostInvokePayload = append(hostInvokePayload, sce.EventDataParam{Name: "_sce_deadline_ms", Value: sceValue})
			}
			hostInvokeParams["answer_schema"] = append(hostInvokeParams["answer_schema"], "urn:sce:schema:lift_answer:2")
			hostInvokePayload = append(hostInvokePayload, sce.EventDataParam{Name: "answer_schema", Value: "urn:sce:schema:lift_answer:2"})
			if requestRefused {
				continue
			}
			hostInvokeEventData := ""
			if len(hostInvokePayload) > 0 {
				hostInvokeEventData = sce.BuildJSONFromTypedParams(hostInvokePayload)
			}
			if !engine.PerformHostInvoke(sce.HostInvokeRequest{
				ProcessorType: "sce-host-model-generate",
				InvokeID:      "gen",
				Src:           hostInvokeSrc,
				Params:        hostInvokeParams,
				EventData:     hostInvokeEventData,
				Content:       hostInvokeContent,
			}) {
				// W3C SCXML 6.4.1: declared but no invoker registered. The
				// document asked for a process to be run and none was, which
				// is the same fact as an unsupported type — so the same
				// event, rather than a silence that reads as started.
				engine.Raise(sce.NewPlatformError(StaticModelHarnessEventErrorExecution, "<invoke> names an invoker the host declared but never registered"))
			}
			continue
		}
	}
}

