// PopulateEventMetadata stores pending event metadata (W3C SCXML 5.10).
// Note: event name is set separately via setCurrentEvent(); metadata supplies
// only the name the event ARRIVED under, when that is not its value's own.
func (p *StaticModelHarnessPolicy) PopulateEventMetadata(meta *sce.EventMetadata) {
	// NL→IR Item C1 Path A: lift the dequeued event's typed payload from the
	// type-erased carrier into the typed policy field the native guards read
	// (twin of the C11 pop loop's `sm->pending_payload = evt.payload`).
	p.pendingPayloadTag = StaticModelHarnessPayloadTagNone
	switch v := meta.TypedPayload.(type) {
	case StaticModelHarnessDoneInvokeGenPayload:
		p.pendingPayloadTag = StaticModelHarnessPayloadTagDoneInvokeGen
		p.pendingDoneInvokeGenPayload = v
	case StaticModelHarnessHarnessOfferPayload:
		p.pendingPayloadTag = StaticModelHarnessPayloadTagHarnessOffer
		p.pendingHarnessOfferPayload = v
	case StaticModelHarnessHarnessStartPayload:
		p.pendingPayloadTag = StaticModelHarnessPayloadTagHarnessStart
		p.pendingHarnessStartPayload = v
	}

	p.pendingEventData = meta.Data
}

// LiftTypedPayload binds the dequeued event's typed `_event.data` view from
// the data it carries (NL→IR Item C1 Path A).
//
// The typed carrier PopulateEventMetadata reads is filled by one producer, the
// generated Raise<Event> inject seam. Every other producer — <send> with
// <param>, an invoke forwarding either way, autoforward, BasicHTTP, mesh —
// fills EventMetadata.Data, so the schema's fields are read out of that here.
// A refusal is returned, on which the engine refuses the delivery whole and
// takes an error.execution in its place (docs/adr/0086, section 4.2).
func (p *StaticModelHarnessPolicy) LiftTypedPayload(event StaticModelHarnessEvent, meta *sce.EventMetadata) error {
	// A typed carrier already bound the view, so the producer was the
	// inject seam and there is nothing to read out of `Data`.
	if p.pendingPayloadTag != StaticModelHarnessPayloadTagNone {
		return nil
	}
	switch event {
	case StaticModelHarnessEventDoneInvokeGen:
		fields, err := sce.LiftPayload(meta.Data)
		if err != nil {
			return err
		}
		var payload StaticModelHarnessDoneInvokeGenPayload
		if payload.error, err = sce.PayloadTextWithin(fields, "error", 24); err != nil {
			return err
		}
		if payload.text, err = sce.PayloadTextWithin(fields, "text", 4096); err != nil {
			return err
		}
		if payload.constrained, err = sce.PayloadBool(fields, "constrained"); err != nil {
			return err
		}
		if payload.model, err = sce.PayloadTextWithin(fields, "model", 128); err != nil {
			return err
		}
		if payload.prompt_tokens, err = sce.PayloadUnsigned[uint32](fields, "prompt_tokens"); err != nil {
			return err
		}
		if payload.answer_tokens, err = sce.PayloadUnsigned[uint32](fields, "answer_tokens"); err != nil {
			return err
		}
		if payload.finish, err = sce.PayloadTextWithin(fields, "finish", 16); err != nil {
			return err
		}
		p.pendingDoneInvokeGenPayload = payload
		p.pendingPayloadTag = StaticModelHarnessPayloadTagDoneInvokeGen
	case StaticModelHarnessEventHarnessOffer:
		fields, err := sce.LiftPayload(meta.Data)
		if err != nil {
			return err
		}
		var payload StaticModelHarnessHarnessOfferPayload
		if payload.id, err = sce.PayloadUnsigned[uint32](fields, "id"); err != nil {
			return err
		}
		p.pendingHarnessOfferPayload = payload
		p.pendingPayloadTag = StaticModelHarnessPayloadTagHarnessOffer
	case StaticModelHarnessEventHarnessStart:
		fields, err := sce.LiftPayload(meta.Data)
		if err != nil {
			return err
		}
		var payload StaticModelHarnessHarnessStartPayload
		if payload.request, err = sce.PayloadTextWithin(fields, "request", 512); err != nil {
			return err
		}
		p.pendingHarnessStartPayload = payload
		p.pendingPayloadTag = StaticModelHarnessPayloadTagHarnessStart
	}
	return nil

}

